<template>
  <div class="app">
    <div id="load">
      <div class="load_hoshi">
        <img draggable="false" src="@/assets/hoshi_w.svg" alt="" />
      </div>
    </div>
    <router-view @openSound="openSound"/>
    <el-dialog :visible="showDialog" :show-close="false" :close-on-click-modal="false" :title="firstDiag? 'Before playing...' : 'Sound settings'">
      <div>Would you like to enable sound?</div>
      <span slot="footer" class="dialog-footer">
    <el-button @click="doDisableMusic()">No</el-button>
    <el-button type="primary" @click="doEnableMusic">Yes</el-button>
  </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: "App",
  props: {},
  data() {
    return {
      showDialog: false,
      bgm: undefined,
      firstDiag: true
    };
  },
  methods: {
    openSound(info){
      this.firstDiag = info;
      this.showDialog = true;
    },
    doDisableMusic(){
      this.bgm.pause();
      this.bgm.currentTime = 0;
      this.showDialog = false;
      if (this.firstDiag){
        this.makeLoadFade();
        setTimeout(() => {
          this.makeLoadDisappear();
        }, 800);
      }
    },
    doEnableMusic(){
      this.bgm.play().catch(error => {
        console.error("Failed to play music automatically:", error);
        alert("Failed to play music.");
      });
      this.bgm.loop = true;
      this.showDialog = false;
      if (this.firstDiag){
        this.makeLoadFade();
        setTimeout(() => {
          this.makeLoadDisappear();
        }, 800);
      }
    },
    makeLoadDisappear() {
      document.getElementById('load').style.display =  "none";
      // console.log($("#load").css("display"));
    },

    makeLoadFade() {
      document.getElementById('load').style.opacity = 0;
    },
  },
  created() {
    if (this.$route.path != '/home'){
      this.$router.replace("/home");
    }
    this.bgm = new Audio("music/magic.ogg");
    setTimeout(() => {this.showDialog = true}, 0)

    // if (this.$route.path != '/'){
    //
    // }
  },
};
</script>
